<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\Accessor\UserAccessTemporalCodeRegisterCodeUrlAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAccessTemporalCodeRegisterCodeUrlAccessor trait.
 *
 * Covers null default, string/VO assignment via withRegisterCodeUrl,
 * getRegisterCodeUrl/registerCodeUrl accessors, and isRegisterCodeUrlChanged with/without original.
 */
class UserAccessTemporalCodeRegisterCodeUrlAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRegisterCodeUrl creates a new instance with the RegisterCodeUrl set
     * from a string value, and getRegisterCodeUrl returns the primitive string.
     */
    public function testWithRegisterCodeUrlFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRegisterCodeUrlAccessorUnitTest();

        // Act
        $result = $holder->withRegisterCodeUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getRegisterCodeUrl());
    }
    /**
     * Asserts that withregisterCodeUrl has access to the value object
     * from a string value, and getRegisterCodeUrl returns the primitive string.
     */
    public function testWithRegisterCodeUrlFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRegisterCodeUrlAccessorUnitTest();

        // Act
        $result = $holder->withRegisterCodeUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->registerCodeUrl()->value());
    }
    public function testChangedRegisterCodeUrl(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRegisterCodeUrlAccessorUnitTest();
        $original = $holder->withRegisterCodeUrl('one');
        $same = $holder->withRegisterCodeUrl('one');
        $modified = $holder->withRegisterCodeUrl('other');

        // Act
        $unchanged = $holder->isRegisterCodeUrlChanged();
        $withSame = $original->isRegisterCodeUrlChanged($same);
        $withDiferent = $original->isRegisterCodeUrlChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserAccessTemporalCodeRegisterCodeUrlAccessorUnitTest
{
    use UserAccessTemporalCodeRegisterCodeUrlAccessor;
}
